import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> {'side':..., 'qty':remaining, 'price':..., 'active':bool}
    bids = []  # max-heap: (-price, seq, id)
    asks = []  # min-heap: (price, seq, id)
    seq_counter = 0

    def add_to_book(side, oid, price, qty):
        nonlocal seq_counter
        seq_counter += 1
        orders_info[oid] = {'side': side, 'qty': qty, 'price': price, 'active': True}
        if side == 'buy':
            heapq.heappush(bids, (-price, seq_counter, oid))
        else:
            heapq.heappush(asks, (price, seq_counter, oid))

    def pop_valid_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    def match_incoming(side, oid, price, qty, is_market):
        # returns remaining qty after matching
        remaining = qty
        if side == 'buy':
            opp_heap = asks
        else:
            opp_heap = bids

        while remaining > 0:
            top = pop_valid_top(opp_heap)
            if top is None:
                break
            resting_id = top[2]
            resting_info = orders_info[resting_id]
            resting_price = resting_info['price']

            if not is_market:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            heapq.heappop(opp_heap)

            trade_qty = min(remaining, resting_info['qty'])
            trade_price = resting_price

            if side == 'buy':
                trades.append([oid, resting_id, trade_price, trade_qty])
            else:
                trades.append([resting_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            resting_info['qty'] -= trade_qty

            if resting_info['qty'] > 0:
                # push back
                heapq.heappush(opp_heap, top)
            else:
                resting_info['active'] = False

        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, oid, price, qty, is_market=False)
            if remaining > 0:
                add_to_book(side, oid, price, remaining)
            else:
                orders_info[oid] = {'side': side, 'qty': 0, 'price': price, 'active': False}
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, oid, price, qty, is_market=False)
            orders_info[oid] = {'side': side, 'qty': 0, 'price': price, 'active': False}
        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, oid, None, qty, is_market=True)
            orders_info[oid] = {'side': side, 'qty': 0, 'price': None, 'active': False}
        elif typ == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False

    return trades

